import React, { Component } from 'react';
import { CButton, CCard, CCardBody, CCol, CInput, CRow, CTextarea } from '@coreui/react';
import { requestHeaderPOSTWithAuth, requestHeaderPUTWithAuth, requestHeaderDELETEWithAuth } from 'src/Rest-API/Header';
import { getUserDataFromLocalStorage, logoutProcedureForLocalStorage } from 'src/Utils/AuthRelatedThings';
import { Logger, reloadPage } from '../../Utils/Utils';
import { Loading } from '../Statuses/Statuses';
import { BACKEND_NEXUS_APP_BASE_URL } from 'src/Rest-API/EnvironmentSpecificThings';
import StatusModal from '../Modals/StatusModal';
import FailureModal from '../Modals/FailureModal';

const FILE_NAME = "DearDiary.js";

// Local date -> "YYYY-MM-DD" (avoids UTC shift from toISOString)
function getTodayDate() {
    const d = new Date();
    const yyyy = d.getFullYear();
    const mm = String(d.getMonth() + 1).padStart(2, '0');
    const dd = String(d.getDate()).padStart(2, '0');
    return `${yyyy}-${mm}-${dd}`;
}

function getAdjacentDate(dateStr, offset) {
    const d = new Date(dateStr + 'T00:00:00');
    d.setDate(d.getDate() + offset);
    const yyyy = d.getFullYear();
    const mm = String(d.getMonth() + 1).padStart(2, '0');
    const dd = String(d.getDate()).padStart(2, '0');
    return `${yyyy}-${mm}-${dd}`;
}

function getWeekday(dateStr) {
    const days = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
    const d = new Date(dateStr + 'T00:00:00');
    return days[d.getDay()];
}

// Backend entryTime is "yyyy-MM-dd HH:mm:ss". Extract the "HH:mm" part for display / <input type=time>.
const extractTime = (entryTime) => {
    if (!entryTime || entryTime.indexOf(' ') < 0) return '';
    return entryTime.split(' ')[1].substring(0, 5);
};

// Current clock time as "HH:mm"
const nowHHmm = () => {
    const d = new Date();
    return String(d.getHours()).padStart(2, '0') + ':' + String(d.getMinutes()).padStart(2, '0');
};

// Build backend timestamp "yyyy-MM-dd HH:mm" (minute precision) from a day string + "HH:mm".
// When no time is provided, default to the current time (now).
const buildEntryTime = (dayStr, hhmm) => {
    const time = (hhmm && hhmm.length >= 4) ? hhmm : nowHHmm();
    return `${dayStr} ${time}`;
};

const EMPTY_FORM = {
    id: null,
    title: '',
    details: '',
    time: '',
    selectedFeelings: [],
};

class DearDiary extends Component {

    constructor(props) {
        super(props);
        this.formRef = React.createRef();
        this.state = {
            selectedDate: getTodayDate(),
            entries: [],
            isLoaded: false,

            // add / edit form (inline)
            showForm: false,
            form: { ...EMPTY_FORM },
            formHighlight: false,

            // feelings type-ahead
            feelingQuery: '',
            feelingSuggestions: [],
            feelingSearchLoading: false,
            feelingDropdownOpen: false,
            feelingCreating: false,

            // delete confirmation is handled via window.confirm (matching TimeLogs)

            // status / failure modals
            loadingModalVisible: false,
            loadingModalState: 0,
            failureModalVisible: false,
        };
    }

    componentDidMount() {
        document.title = "Dear Diary";
        this.fetchEntries();
    }

    componentWillUnmount() {
        if (this.feelingSearchTimer) clearTimeout(this.feelingSearchTimer);
    }

    // ----------------------------- data fetching -----------------------------

    handleAuthFailure = () => {
        this.setState({ loadingModalVisible: false, failureModalVisible: true });
        setTimeout(() => { logoutProcedureForLocalStorage(); reloadPage(); }, 500);
    }

    fetchEntries = () => {
        const { selectedDate } = this.state;
        const userData = getUserDataFromLocalStorage();
        const API_URL = BACKEND_NEXUS_APP_BASE_URL + '/v1/diary/list';

        this.setState({ isLoaded: false });

        // day-based listing: service returns a plain array (not a Page)
        fetch(API_URL, requestHeaderPOSTWithAuth(JSON.stringify({ day: selectedDate }), userData.authToken))
        .then(response => {
            if (response.status === 200) return response.json();
            if (response.status === 401) { logoutProcedureForLocalStorage(); reloadPage(); }
            throw new Error("HTTP status is " + response.status);
        })
        .then(result => {
            Logger(FILE_NAME, "fetchEntries", "SUCCESS", "result", result);
            const data = result.data;
            const entries = Array.isArray(data) ? data : (data.content || []);
            this.setState({ isLoaded: true, entries });
        })
        .catch(error => {
            Logger(FILE_NAME, "fetchEntries", "ERROR", "error", error);
            this.setState({ isLoaded: true, entries: [] });
        });
    }

    // Type-ahead: query the feelings catalog via the search param as the user types (debounced).
    // Backend requires >= 2 chars for search; with size > 0 the response `data` is a Page.
    searchFeelings = (query) => {
        const userData = getUserDataFromLocalStorage();
        const API_URL = BACKEND_NEXUS_APP_BASE_URL + '/v1/feeling/list';
        const reqData = { search: query.trim(), page: 1, size: 20 };

        this.setState({ feelingSearchLoading: true });

        fetch(API_URL, requestHeaderPOSTWithAuth(JSON.stringify(reqData), userData.authToken))
        .then(response => {
            if (response.status === 200) return response.json();
            if (response.status === 401) { this.handleAuthFailure(); }
            throw new Error("HTTP status is " + response.status);
        })
        .then(result => {
            Logger(FILE_NAME, "searchFeelings", "SUCCESS", "result", result);
            const data = result.data;
            const suggestions = Array.isArray(data) ? data : (data.content || []);
            this.setState({ feelingSuggestions: suggestions, feelingSearchLoading: false, feelingDropdownOpen: true });
        })
        .catch(error => {
            Logger(FILE_NAME, "searchFeelings", "ERROR", "error", error);
            this.setState({ feelingSuggestions: [], feelingSearchLoading: false });
        });
    }

    // Create a brand-new feeling (when the typed name is not in the catalog), then attach it.
    // Backend lowercases the name on save, so we add the canonical name from the response.
    createFeeling = (rawName) => {
        const name = rawName.trim();
        if (!name) return;

        const userData = getUserDataFromLocalStorage();
        const API_URL = BACKEND_NEXUS_APP_BASE_URL + '/v1/feeling';

        this.setState({ feelingCreating: true });

        fetch(API_URL, requestHeaderPOSTWithAuth(JSON.stringify({ name }), userData.authToken))
        .then(response => {
            if (response.status === 200) return response.json();
            if (response.status === 401) { this.handleAuthFailure(); }
            throw new Error("HTTP status is " + response.status);
        })
        .then(result => {
            Logger(FILE_NAME, "createFeeling", "SUCCESS", "result", result);
            const created = result.data;
            const canonicalName = (created && created.name) ? created.name : name;
            this.setState({ feelingCreating: false });
            this.addFeeling(canonicalName);
        })
        .catch(error => {
            Logger(FILE_NAME, "createFeeling", "ERROR", "error", error);
            this.setState({ feelingCreating: false });
            alert("Could not create feeling '" + name + "'. It may already exist or the request failed.");
        });
    }

    handleFeelingQueryChange = (e) => {
        const query = e.target.value;
        this.setState({ feelingQuery: query });

        if (this.feelingSearchTimer) clearTimeout(this.feelingSearchTimer);

        if (query.trim().length < 2) {
            this.setState({ feelingSuggestions: [], feelingDropdownOpen: false, feelingSearchLoading: false });
            return;
        }

        // debounce network calls while typing
        this.feelingSearchTimer = setTimeout(() => this.searchFeelings(query), 250);
    }

    // ----------------------------- date navigation -----------------------------

    onDateChange = (e) => {
        if (!e.target.value) return;
        this.setState({ selectedDate: e.target.value }, this.fetchEntries);
    }

    goToDate = (dateStr) => {
        this.setState({ selectedDate: dateStr }, this.fetchEntries);
    }

    isToday = () => this.state.selectedDate === getTodayDate();

    // ----------------------------- add / edit form -----------------------------

    resetFeelingSearch = () => {
        if (this.feelingSearchTimer) clearTimeout(this.feelingSearchTimer);
        this.setState({ feelingQuery: '', feelingSuggestions: [], feelingSearchLoading: false, feelingDropdownOpen: false });
    }

    openAddForm = () => {
        this.setState({ showForm: true, form: { ...EMPTY_FORM } });
        this.resetFeelingSearch();
    }

    openEditForm = (entry) => {
        this.setState({
            showForm: true,
            form: {
                id: entry.id,
                title: entry.title || '',
                details: entry.details || '',
                time: extractTime(entry.entryTime),
                selectedFeelings: entry.feelings ? [...entry.feelings] : [],
            },
            formHighlight: true,
        }, () => {
            if (this.formRef.current) {
                this.formRef.current.scrollIntoView({ behavior: 'smooth', block: 'start' });
            }
            setTimeout(() => this.setState({ formHighlight: false }), 1500);
        });
        this.resetFeelingSearch();
    }

    closeForm = () => {
        this.setState({ showForm: false, form: { ...EMPTY_FORM } });
        this.resetFeelingSearch();
    }

    handleFormChange = (field, value) => {
        this.setState(prev => ({ form: { ...prev.form, [field]: value } }));
    }

    addFeeling = (feelingName) => {
        this.setState(prev => {
            const selected = prev.form.selectedFeelings;
            const next = selected.includes(feelingName) ? selected : [...selected, feelingName];
            return { form: { ...prev.form, selectedFeelings: next } };
        });
        this.resetFeelingSearch();
    }

    removeFeeling = (feelingName) => {
        this.setState(prev => ({
            form: { ...prev.form, selectedFeelings: prev.form.selectedFeelings.filter(f => f !== feelingName) },
        }));
    }

    handleFormSubmit = (e) => {
        e.preventDefault();
        const { form, selectedDate } = this.state;

        if (!form.title || form.title.trim() === '') {
            alert("Title is required");
            return;
        }

        const payload = {
            title: form.title.trim(),
            details: form.details && form.details.trim() !== '' ? form.details.trim() : null,
            feelings: form.selectedFeelings,
            entryTime: buildEntryTime(selectedDate, form.time),
        };

        Logger(FILE_NAME, "handleFormSubmit", "", "payload", payload);

        const userData = getUserDataFromLocalStorage();
        const isUpdate = form.id != null;
        const API_URL = isUpdate
            ? BACKEND_NEXUS_APP_BASE_URL + '/v1/diary/' + form.id
            : BACKEND_NEXUS_APP_BASE_URL + '/v1/diary';
        const request = isUpdate
            ? requestHeaderPUTWithAuth(JSON.stringify(payload), userData.authToken)
            : requestHeaderPOSTWithAuth(JSON.stringify(payload), userData.authToken);

        this.setState({ showForm: false, loadingModalVisible: true, loadingModalState: 0 });

        fetch(API_URL, request)
        .then(response => {
            if (response.status === 200) return response.json();
            if (response.status === 401) { this.handleAuthFailure(); }
            throw new Error("HTTP status is " + response.status);
        })
        .then(result => {
            Logger(FILE_NAME, "handleFormSubmit", "API_RESPONSE", "result", result);
            this.setState({ loadingModalState: 1 });
            setTimeout(() => {
                this.setState({ loadingModalVisible: false, loadingModalState: 0, form: { ...EMPTY_FORM } });
                this.fetchEntries();
            }, 800);
        })
        .catch(error => {
            Logger(FILE_NAME, "handleFormSubmit", "API_ERROR", "error", error);
            this.setState({ loadingModalVisible: false, failureModalVisible: true });
        });
    }

    // ----------------------------- delete -----------------------------

    handleDelete = (entry) => {
        if (!window.confirm(`Permanently delete the entry "${entry.title}"? This cannot be undone.`)) return;

        const userData = getUserDataFromLocalStorage();
        const API_URL = BACKEND_NEXUS_APP_BASE_URL + '/v1/diary/' + entry.id;

        this.setState({ loadingModalVisible: true, loadingModalState: 0 });

        fetch(API_URL, requestHeaderDELETEWithAuth(null, userData.authToken))
        .then(response => {
            if (response.status === 200) return response.json();
            if (response.status === 401) { this.handleAuthFailure(); }
            throw new Error("HTTP status is " + response.status);
        })
        .then(result => {
            Logger(FILE_NAME, "handleDelete", "API_RESPONSE", "result", result);
            this.setState({ loadingModalState: 1 });
            setTimeout(() => {
                this.setState({ loadingModalVisible: false, loadingModalState: 0 });
                this.fetchEntries();
            }, 800);
        })
        .catch(error => {
            Logger(FILE_NAME, "handleDelete", "API_ERROR", "error", error);
            this.setState({ loadingModalVisible: false, failureModalVisible: true });
        });
    }

    // ----------------------------- render -----------------------------

    render() {
        const {
            selectedDate, entries, isLoaded, showForm,
        } = this.state;

        const styles = {
            header: {
                background: 'rgba(255, 255, 255, 0.95)',
                backdropFilter: 'blur(10px)',
                borderRadius: '16px',
                padding: '28px 32px',
                marginBottom: '24px',
                boxShadow: '0 10px 40px rgba(0, 0, 0, 0.1)',
                border: '1px solid rgba(255, 255, 255, 0.8)',
            },
            title: {
                fontSize: '2em',
                fontWeight: '800',
                background: 'linear-gradient(135deg, #667eea, #764ba2)',
                WebkitBackgroundClip: 'text',
                WebkitTextFillColor: 'transparent',
                margin: 0,
            },
            controls: {
                display: 'flex',
                alignItems: 'center',
                gap: '12px',
                flexWrap: 'wrap',
                marginTop: '16px',
                padding: '16px 20px',
                background: 'linear-gradient(135deg, #f8f9ff, #f0f2ff)',
                borderRadius: '12px',
                border: '1px solid #e8ecff',
            },
            weekday: {
                fontWeight: '600',
                color: '#764ba2',
                fontSize: '0.95em',
                padding: '4px 12px',
                background: 'rgba(118, 75, 162, 0.08)',
                borderRadius: '20px',
            },
            navBtn: {
                background: 'white',
                border: '2px solid #e8ecff',
                borderRadius: '8px',
                padding: '6px 12px',
                cursor: 'pointer',
                fontWeight: '700',
                fontSize: '1.1em',
                transition: 'all 0.2s',
            },
            todayBtn: {
                background: 'linear-gradient(135deg, #667eea, #764ba2)',
                color: 'white',
                border: 'none',
                borderRadius: '8px',
                padding: '6px 14px',
                cursor: 'pointer',
                fontWeight: '600',
                fontSize: '0.85em',
                boxShadow: '0 2px 8px rgba(102, 126, 234, 0.3)',
            },
            addBtn: {
                borderRadius: '10px',
                fontWeight: '600',
                padding: '12px 28px',
                fontSize: '1em',
                background: 'linear-gradient(135deg, #667eea, #764ba2)',
                border: 'none',
                color: 'white',
            },
        };

        return (
            <div>
                {/* Header */}
                <div style={styles.header}>
                    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: '12px' }}>
                        <h1 style={styles.title}>📖 Dear Diary</h1>
                        <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
                            {!showForm && (
                                <CButton onClick={this.openAddForm} style={styles.addBtn}>➕ New Entry</CButton>
                            )}
                            <CButton color="light" onClick={this.fetchEntries} title="Refresh" style={{ borderRadius: '10px', fontWeight: '600', padding: '8px 14px' }}>🔄</CButton>
                        </div>
                    </div>

                    {/* Controls */}
                    <div style={styles.controls}>
                        <button onClick={() => this.goToDate(getTodayDate())} style={styles.todayBtn} title="Jump to today">Today</button>
                        <span style={{ color: '#cbd5e0' }}>|</span>
                        <label style={{ fontWeight: '700', margin: 0, color: '#4a5568', fontSize: '0.9em' }}>📅 Date:</label>
                        <button onClick={() => this.goToDate(getAdjacentDate(selectedDate, -1))} style={styles.navBtn} title="Previous day">◀</button>
                        <CInput
                            type="date"
                            value={selectedDate}
                            onChange={this.onDateChange}
                            style={{ maxWidth: '180px', borderRadius: '8px', border: '2px solid #e8ecff', fontWeight: '500' }}
                        />
                        <button onClick={() => this.goToDate(getAdjacentDate(selectedDate, 1))} style={styles.navBtn} title="Next day">▶</button>
                        <span style={styles.weekday}>{getWeekday(selectedDate)}</span>
                    </div>
                </div>

                {/* Form */}
                {showForm && this.renderForm()}

                {/* Content */}
                <div>
                    {!isLoaded && <Loading />}
                    {isLoaded && this.renderEntries(entries)}
                </div>

                <StatusModal visible={this.state.loadingModalVisible} loadingModalState={this.state.loadingModalState} />
                <FailureModal visible={this.state.failureModalVisible} />
            </div>
        );
    }

    renderEntries(entries) {
        if (entries.length === 0) {
            return (
                <div style={{ textAlign: 'center', padding: '60px 40px', color: '#a0aec0' }}>
                    <div style={{ fontSize: '3em', marginBottom: '12px' }}>📭</div>
                    <p style={{ fontStyle: 'italic', fontSize: '1.1em', fontWeight: '500' }}>No entries for this day.</p>
                    <p style={{ fontSize: '0.9em', color: '#cbd5e0' }}>Click "New Entry" to write one</p>
                </div>
            );
        }

        return (
            <div style={{ borderRadius: '12px', border: '1px solid #e2e8f0', boxShadow: '0 2px 8px rgba(0,0,0,0.04)', overflow: 'hidden' }}>
                <div style={{ background: 'linear-gradient(135deg, #667eea, #764ba2)', padding: '12px 20px', color: 'white', fontWeight: '700', fontSize: '0.9em', letterSpacing: '0.5px', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                    <span>📖 ENTRIES</span>
                    <span style={{ fontFamily: 'monospace', fontSize: '1em' }}>{entries.length} {entries.length === 1 ? 'entry' : 'entries'}</span>
                </div>
                <div>
                    {entries.map((entry, index) => (
                        <div key={'entry-' + entry.id} style={{ padding: '16px 20px', borderBottom: '1px solid #edf2f7', background: index % 2 === 0 ? '#ffffff' : '#f7fafc', borderLeft: '4px solid #764ba2' }}>
                            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', gap: '12px' }}>
                                <div style={{ minWidth: 0 }}>
                                    <div style={{ fontWeight: '700', color: '#2d3748', fontSize: '1.05em' }}>{entry.title}</div>
                                    <div style={{ fontFamily: 'monospace', fontSize: '0.8em', color: '#a0aec0', marginTop: '2px' }}>🕒 {extractTime(entry.entryTime) || '—'}</div>
                                </div>
                                <div style={{ display: 'flex', gap: '6px', flexShrink: 0 }}>
                                    <CButton color="info" size="sm" onClick={() => this.openEditForm(entry)} style={{ borderRadius: '8px', padding: '4px 10px' }}>✏️</CButton>
                                    <CButton color="danger" size="sm" onClick={() => this.handleDelete(entry)} style={{ borderRadius: '8px', padding: '4px 10px' }}>🗑️</CButton>
                                </div>
                            </div>

                            {entry.details && (
                                <p style={{ marginTop: '10px', marginBottom: 0, whiteSpace: 'pre-wrap', color: '#4a5568', fontSize: '0.92em' }}>{entry.details}</p>
                            )}

                            {entry.feelings && entry.feelings.length > 0 && (
                                <div style={{ marginTop: '10px', display: 'flex', gap: '6px', flexWrap: 'wrap' }}>
                                    {entry.feelings.map((f, i) => (
                                        <span
                                            key={'f-' + entry.id + '-' + i}
                                            style={{
                                                background: 'rgba(118, 75, 162, 0.1)',
                                                color: '#6b46c1',
                                                border: '1px solid rgba(118, 75, 162, 0.25)',
                                                borderRadius: '20px',
                                                padding: '2px 12px',
                                                fontSize: '0.8em',
                                                fontWeight: '600',
                                            }}
                                        >
                                            {f}
                                        </span>
                                    ))}
                                </div>
                            )}
                        </div>
                    ))}
                </div>
            </div>
        );
    }

    renderForm() {
        const {
            form, formHighlight, selectedDate,
            feelingQuery, feelingSuggestions, feelingSearchLoading, feelingDropdownOpen, feelingCreating,
        } = this.state;
        const isEditing = form.id != null;
        const visibleSuggestions = feelingSuggestions.filter(f => !form.selectedFeelings.includes(f.name));

        // Offer to create the typed feeling when it matches nothing (in suggestions or already-selected), case-insensitive.
        const trimmedQuery = feelingQuery.trim();
        const queryLower = trimmedQuery.toLowerCase();
        const matchesExisting =
            feelingSuggestions.some(f => f.name.toLowerCase() === queryLower) ||
            form.selectedFeelings.some(name => name.toLowerCase() === queryLower);
        const canCreate = trimmedQuery.length >= 2 && !matchesExisting;

        const inputStyle = { borderRadius: '10px', border: '2px solid #e8ecff', padding: '10px 14px' };
        const labelStyle = { fontWeight: '600', color: '#4a5568', fontSize: '0.9em', marginBottom: '6px', display: 'block' };

        return (
            <div ref={this.formRef}>
                <CCard className="mb-4" style={{ border: 'none', borderRadius: '16px', boxShadow: formHighlight ? '0 0 0 4px rgba(102, 126, 234, 0.5), 0 10px 40px rgba(102, 126, 234, 0.25)' : '0 10px 40px rgba(102, 126, 234, 0.15)', overflow: 'hidden', transition: 'box-shadow 0.3s ease' }}>
                    <div style={{ background: 'linear-gradient(135deg, #667eea, #764ba2)', padding: '16px 32px', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                        <h5 style={{ color: 'white', margin: 0, fontWeight: '700' }}>{isEditing ? '✏️ Edit Diary Entry' : '➕ New Diary Entry'}</h5>
                        <span style={{ color: 'rgba(255,255,255,0.85)', fontSize: '0.85em' }}>{getWeekday(selectedDate)}, {selectedDate}</span>
                    </div>
                    <CCardBody style={{ background: '#fafbff', padding: '28px 32px' }}>
                        <form onSubmit={this.handleFormSubmit}>
                            <CRow>
                                <CCol md="9">
                                    <div style={{ marginBottom: '16px' }}>
                                        <label style={labelStyle}>Title <span style={{ color: '#e53e3e' }}>*</span></label>
                                        <CInput
                                            value={form.title}
                                            onChange={(e) => this.handleFormChange('title', e.target.value)}
                                            placeholder="Title of the entry"
                                            required
                                            style={inputStyle}
                                        />
                                    </div>
                                </CCol>
                                <CCol md="3">
                                    <div style={{ marginBottom: '16px' }}>
                                        <label style={labelStyle}>Time <span style={{ color: '#a0aec0', fontWeight: '400' }}>(optional)</span></label>
                                        <div style={{ display: 'flex', gap: '6px', alignItems: 'center' }}>
                                            <CInput
                                                type="time"
                                                value={form.time}
                                                onChange={(e) => this.handleFormChange('time', e.target.value)}
                                                style={{ ...inputStyle, flex: 1 }}
                                            />
                                            {form.time && (
                                                <button
                                                    type="button"
                                                    onClick={() => this.handleFormChange('time', '')}
                                                    title="Clear time"
                                                    style={{ padding: '8px 10px', borderRadius: '8px', border: '2px solid #e8ecff', background: 'white', cursor: 'pointer', fontSize: '0.85em', color: '#a0aec0', lineHeight: 1 }}
                                                >
                                                    ✕
                                                </button>
                                            )}
                                        </div>
                                    </div>
                                </CCol>
                            </CRow>

                            <div style={{ marginBottom: '16px' }}>
                                <label style={labelStyle}>Details</label>
                                <CTextarea
                                    rows="5"
                                    value={form.details}
                                    onChange={(e) => this.handleFormChange('details', e.target.value)}
                                    placeholder="What happened today..."
                                    style={inputStyle}
                                />
                            </div>

                            <div style={{ marginBottom: '16px' }}>
                                <label style={labelStyle}>Feelings</label>

                                {/* selected feelings as removable chips */}
                                {form.selectedFeelings.length > 0 && (
                                    <div style={{ display: 'flex', gap: '6px', flexWrap: 'wrap', marginBottom: '8px' }}>
                                        {form.selectedFeelings.map((name, i) => (
                                            <span
                                                key={'sel-' + i}
                                                style={{
                                                    background: 'rgba(118, 75, 162, 0.1)',
                                                    color: '#6b46c1',
                                                    border: '1px solid rgba(118, 75, 162, 0.25)',
                                                    borderRadius: '20px',
                                                    padding: '3px 8px 3px 12px',
                                                    fontSize: '0.82em',
                                                    fontWeight: '600',
                                                    display: 'inline-flex',
                                                    alignItems: 'center',
                                                    gap: '6px',
                                                }}
                                            >
                                                {name}
                                                <span
                                                    role="button"
                                                    title="Remove"
                                                    onClick={() => this.removeFeeling(name)}
                                                    style={{ cursor: 'pointer', fontWeight: 'bold', lineHeight: 1 }}
                                                >
                                                    ✕
                                                </span>
                                            </span>
                                        ))}
                                    </div>
                                )}

                                {/* type-ahead input with suggestion dropdown */}
                                <div style={{ position: 'relative' }}>
                                    <CInput
                                        type="text"
                                        placeholder="Type to search feelings (min 2 chars)..."
                                        value={feelingQuery}
                                        onChange={this.handleFeelingQueryChange}
                                        onFocus={() => { if (feelingSuggestions.length > 0) this.setState({ feelingDropdownOpen: true }); }}
                                        autoComplete="off"
                                        style={inputStyle}
                                    />

                                    {feelingDropdownOpen && feelingQuery.trim().length >= 2 && (
                                        <div
                                            style={{
                                                position: 'absolute',
                                                top: '100%',
                                                left: 0,
                                                right: 0,
                                                zIndex: 1000,
                                                backgroundColor: '#fff',
                                                border: '2px solid #e8ecff',
                                                borderRadius: '10px',
                                                marginTop: '4px',
                                                maxHeight: '220px',
                                                overflowY: 'auto',
                                                boxShadow: '0 8px 24px rgba(102, 126, 234, 0.18)',
                                            }}
                                        >
                                            {feelingSearchLoading ? (
                                                <div style={{ padding: '10px 14px', color: '#a0aec0' }}>Searching…</div>
                                            ) : (
                                                <>
                                                    {visibleSuggestions.map((f) => (
                                                        <div
                                                            key={'sug-' + f.id}
                                                            role="button"
                                                            onClick={() => this.addFeeling(f.name)}
                                                            onMouseDown={(e) => e.preventDefault()}
                                                            style={{ padding: '10px 14px', cursor: 'pointer', borderBottom: '1px solid #f0f2ff' }}
                                                        >
                                                            <div style={{ fontWeight: '600', color: '#2d3748' }}>{f.name}</div>
                                                            {f.description && (
                                                                <div style={{ fontSize: '0.8em', color: '#a0aec0' }}>{f.description}</div>
                                                            )}
                                                        </div>
                                                    ))}

                                                    {visibleSuggestions.length === 0 && !canCreate && (
                                                        <div style={{ padding: '10px 14px', color: '#a0aec0' }}>No matching feelings</div>
                                                    )}

                                                    {canCreate && (
                                                        <div
                                                            role="button"
                                                            onClick={() => { if (!feelingCreating) this.createFeeling(trimmedQuery); }}
                                                            onMouseDown={(e) => e.preventDefault()}
                                                            style={{ padding: '10px 14px', cursor: feelingCreating ? 'default' : 'pointer', background: '#f8f9ff', borderTop: visibleSuggestions.length > 0 ? '1px solid #e8ecff' : 'none' }}
                                                        >
                                                            <span style={{ fontWeight: '700', color: '#667eea' }}>
                                                                {feelingCreating ? '⏳ Adding…' : `➕ Add "${trimmedQuery}"`}
                                                            </span>
                                                            {!feelingCreating && (
                                                                <span style={{ fontSize: '0.8em', color: '#a0aec0', marginLeft: '6px' }}>as a new feeling</span>
                                                            )}
                                                        </div>
                                                    )}
                                                </>
                                            )}
                                        </div>
                                    )}
                                </div>
                            </div>

                            <div style={{ display: 'flex', justifyContent: 'flex-end', gap: '10px', marginTop: '8px' }}>
                                <CButton color="light" type="button" onClick={this.closeForm} style={{ borderRadius: '10px', fontWeight: '600', padding: '10px 22px', border: '2px solid #e8ecff' }}>Cancel</CButton>
                                <CButton type="submit" style={{ borderRadius: '10px', fontWeight: '600', padding: '10px 28px', background: 'linear-gradient(135deg, #667eea, #764ba2)', border: 'none', color: 'white' }}>{isEditing ? 'Update' : 'Create'}</CButton>
                            </div>
                        </form>
                    </CCardBody>
                </CCard>
            </div>
        );
    }
}

export default DearDiary;
